// Assemble the outreach request. Prompt and schema are read from disk, so
// prompts/outreach.md and agents/outreach/schema.json stay the single sources
// of truth.

// The model and the language map are the window's: regional leads at night
// with the large model, everyone else by day (Outreach Window).
const slot = $('Outreach Window').first().json;
const MODEL = slot.model;

function fencedBlockUnder(markdown, heading) {
  const section = markdown.split(new RegExp('^##\\s+' + heading + '\\s*$', 'm'))[1];
  if (!section) throw new Error('prompts/outreach.md: no "## ' + heading + '" heading');
  const fence = section.match(/```[a-z]*\n([\s\S]*?)\n```/);
  if (!fence) throw new Error('prompts/outreach.md: no fenced block under "## ' + heading + '"');
  return fence[1].trim();
}

const doc = $('Prompt To Text').first().json.data;
const systemPrompt = fencedBlockUnder(doc, 'System prompt');

// Structure, subject-line rules and the offer table live outside the fenced
// system prompt but are part of the instruction. Everything up to the worked
// example goes with it; the example is left out because a local model copies it.
const structureStart = doc.indexOf('## Structure');
const exampleStart = doc.indexOf('## Example');
if (structureStart === -1 || exampleStart === -1) {
  throw new Error('prompts/outreach.md: could not locate the Structure or Example sections');
}
const guidance = doc.slice(structureStart, exampleStart).trim();

// The automation line has its own system prompt, structure and example under
// "## Automation line" in the same file; subject lines, offers and the output
// contract are shared, so they are taken from the infrastructure part.
const automation = (doc.split(/^##\s+Automation line\s*$/m)[1] || '').split(/^##\s+Follow-ups\s*$/m)[0];
const autoFence = (automation.split(/^###\s+System prompt\s*$/m)[1] || '').match(/```[a-z]*\n([\s\S]*?)\n```/);
const autoStructure = automation.indexOf('### Structure');
const autoExample = automation.indexOf('### Example');
if (!autoFence || autoStructure === -1 || autoExample === -1) {
  throw new Error('prompts/outreach.md: "## Automation line" needs a System prompt, a Structure and an Example');
}
const shared = doc.slice(doc.indexOf('## Subject lines'), exampleStart).trim();
const PROMPTS = {
  infrastructure: systemPrompt + '\n\n' + guidance,
  automation: autoFence[1].trim() + '\n\n' + automation.slice(autoStructure, autoExample).trim() + '\n\n' + shared,
};

const catalogue = JSON.parse($('Offers To Text').first().json.data);

// Language by the company's country, from the map Outreach Window built out of
// OUTREACH_LANGUAGES (ISO codes and the country names YC uses). Everything else
// is written in English.
const languageOf = (country) => slot.languages[String(country || '').trim().toUpperCase()] || 'en';
const LANGUAGE_RULES = { sr: fencedBlockUnder(doc, 'Serbian') };
// Appended for a follow-up; the earlier messages go in the brief.
const FOLLOW_UP = fencedBlockUnder(doc, 'Follow-ups');
// A segment's offer (icp_segments.angle, 0024) goes in the brief, and the
// rules for using it are appended to the system prompt.
const SEGMENT_RULES = fencedBlockUnder(doc, 'Segment');
// The call to action is the one variant tested on every first message. The
// lead id picks it, so a re-drafted lead keeps its variant.
const CTA_VARIANTS = {
  A: 'Ask one yes/no question: whether this is how it works for them today, or whether someone already handles it.',
  B: 'Offer to send a one-page example of what the analysis would cover for them, and ask whether they want it.',
};
const ctaOf = (leadId) => (parseInt(String(leadId).replace(/[^0-9a-f]/gi, '').slice(-4), 16) % 2 === 0 ? 'A' : 'B');
const FOLLOWUP_MAX = Number($env.OUTREACH_FOLLOWUP_MAX ?? 2);
const lineOf = (code) => (catalogue.offers.find((o) => o.code === code) || {}).line || 'infrastructure';

const schema = JSON.parse($('Schema To Text').first().json.data);
delete schema.$schema;
delete schema.$id;
delete schema.title;

return $input.all().map((item, i) => {
  const c = item.json;
  const research = c.research_analysis || {};
  // 'none' or a missing offer is the infrastructure line, as it always was.
  const line = lineOf(c.recommended_offer);
  const language = LANGUAGE_RULES[languageOf(c.country)] ? languageOf(c.country) : 'en';
  const offer = c.recommended_offer && c.recommended_offer !== 'none'
    ? c.recommended_offer : catalogue.lines[line].default_offer;

  // A role contact is the company's published general address (info@,
  // office@), with nobody named behind it. The model is told so in as many
  // words, because a model given a blank name invents one.
  const isRole = c.person_kind === 'role';
  const recipient = isRole
    ? [
        'RECIPIENT',
        'Name: none. There is NO named recipient: this goes to the company\'s general address (' +
          c.person_email + '), read by whoever handles it.',
        'Title: none',
        'Do not address, name or guess anyone, and do not assume the reader\'s role. Write to the company.',
      ]
    : [
        'RECIPIENT',
        'Name: ' + c.person_name,
        'Title: ' + (c.person_title || 'unknown'),
      ];

  const step = Number(c.sequence_step || 1);
  const cta = step > 1 ? null : ctaOf(c.lead_id);
  const angle = c.segment_angle || null;
  const followUp = step > 1
    ? [
        'FOLLOW-UP ' + (step - 1) + ' OF ' + FOLLOWUP_MAX +
          (step - 1 >= FOLLOWUP_MAX ? ' - THIS IS THE LAST ONE: say so in one sentence.' : ''),
        '',
        'PREVIOUS MESSAGES (sent, no reply)',
        ...(c.previous || []).map((m) => '--- message ' + m.step + ', sent ' + String(m.sent_at).slice(0, 10) +
          '\nSubject: ' + m.subject + '\n' + m.body),
        '',
      ]
    : [];

  const brief = [
    ...followUp,
    ...recipient,
    '',
    'COMPANY',
    'Name: ' + c.company_name,
    'Domain: ' + c.domain,
    'Industry: ' + (c.industry || 'unknown'),
    'Employees: ' + (c.employee_count === null || c.employee_count === undefined ? 'unknown' : c.employee_count),
    'Summary: ' + (c.description || 'unknown'),
    '',
    'RESEARCH FILE',
    JSON.stringify({
      facts: research.facts || [],
      technology: research.technology || [],
      hiring_signals: research.hiring_signals || [],
      pain_signals: research.pain_signals || [],
      why_now: research.why_now || '',
      unknown: research.unknown || [],
    }, null, 1),
    '',
    'EVIDENCE ROWS (each source_url is checkable; hook_source must be one of these)',
    JSON.stringify(c.signals || [], null, 1),
    '',
    'SOURCES YOU MAY CITE - hook_source must be exactly one of these strings:',
    (c.known_sources || []).join('\n'),
    '',
    'SCORING SAID: ' + (c.lead_reason || ''),
    'LINE: ' + catalogue.lines[line].name,
    'LANGUAGE: ' + (language === 'sr' ? 'Serbian, Latin script (see LANGUAGE in the instructions)' : 'English'),
    'OFFER TO USE: ' + offer,
    ...(angle ? ['', 'SEGMENT: ' + angle] : []),
    ...(angle ? ['COUNTRY: ' + (c.country || 'unknown') + '. ' +
                 (c.country_e_invoicing || 'Nothing is known about its invoicing systems; name none.')] : []),
    ...(cta ? ['CALL TO ACTION: ' + CTA_VARIANTS[cta]] : []),
    '',
    step > 1
      ? 'Write follow-up ' + (step - 1) + '. If there is nothing new worth saying, set "send" to false.'
      : angle
        ? 'Write the first email by the SEGMENT rules. If the research file has nothing specific and sourced'
        : 'Write the first email. If the research file has no specific, current, sourced',
    step > 1 ? '' : angle
      ? 'about this company at all, set "send" to false and say why.'
      : 'problem, set "send" to false and say why. Sending nothing is an acceptable outcome.',
  ];

  return {
    json: {
      agent_run_id: c.agent_run_id,
      lead_id: c.lead_id,
      company_id: c.company_id,
      company_name: c.company_name,
      person_name: c.person_name,
      person_kind: c.person_kind || 'person',
      sequence_step: step,
      line,
      language,
      model: MODEL,
      // Recorded on the outreach row, so results can be counted per segment
      // and per variant (v_segment_results, v_variant_results).
      experiment: { segment: c.segment || null, campaign: c.campaign || null, offer, language, cta, model: MODEL,
                    segment_mode: Boolean(angle) },
      llm_request: {
        model: MODEL,
        temperature: 0.4,
        max_tokens: 4000,
        // Writing is where thinking might have helped, but the qwen models spend
        // their whole budget on it and the draft never arrives. The hard rules
        // are explicit enough to follow directly. See docs/ollama.md.
        reasoning_effort: 'none',
        messages: [
          { role: 'system', content: PROMPTS[line] + (language === 'en' ? '' : '\n\n' + LANGUAGE_RULES[language]) +
              (angle && step === 1 ? '\n\n' + SEGMENT_RULES : '') +
              (step > 1 ? '\n\n' + FOLLOW_UP : '') },
          { role: 'user', content: brief.join('\n') },
        ],
        response_format: {
          type: 'json_schema',
          json_schema: { name: 'outreach', strict: true, schema },
        },
      },
    },
    // Validate And Check finds this request again by paired item, not position.
    pairedItem: { item: i },
  };
});

// Validate the draft, then run the mechanical checks.
//
// prompts/outreach.md lists rules that are checkable without judgement - a word
// ceiling, a list of phrases that must never appear, a hook that must be
// traceable to a source the research actually found. docs/workflows.md names
// them as WF-05's job. They are enforced here rather than trusted to the model,
// and a draft that fails one is stored at 'draft' with the reason.
//
// Nothing is edited to comply. A blocked draft is a draft a human can read and
// judge; a quietly corrected one is a draft nobody ever learns from.

const schema = JSON.parse($('Schema To Text').first().json.data);

// The greeting and the signature are not the model's to write. prompts/
// signature.md holds both and they are appended here, not at send time, so the
// text a human approves is the text that gets sent rather than a summary of it.
//
// Every check below runs on the model's body alone, and that is deliberate: the
// signature carries its own question mark and its own forty words, and neither
// belongs to the 120-word ceiling or to the one-question rule.
function fencedBlockUnder(markdown, heading) {
  const escaped = heading.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const section = markdown.split(new RegExp('^##\\s+' + escaped + '\\s*$', 'm'))[1];
  if (!section) throw new Error('prompts/signature.md: no "## ' + heading + '" heading');
  const fence = section.match(/```[a-z]*\n([\s\S]*?)\n```/);
  if (!fence) throw new Error('prompts/signature.md: no fenced block under "## ' + heading + '"');
  return fence[1].trim();
}
const envelope = $('Signature To Text').first().json.data;
// One greeting and signature per outreach language; the builder picked the
// language from the company's country.
// role_greeting is for a role contact - the company's general address, with
// no name to greet (0022_role_contacts.sql).
const ENVELOPES = {
  en: { greeting: fencedBlockUnder(envelope, 'Greeting'), role_greeting: fencedBlockUnder(envelope, 'Greeting (role)'),
        signature: fencedBlockUnder(envelope, 'Signature'), tagline: 'tagline' },
  sr: { greeting: fencedBlockUnder(envelope, 'Greeting (sr)'), role_greeting: fencedBlockUnder(envelope, 'Greeting (role, sr)'),
        signature: fencedBlockUnder(envelope, 'Signature (sr)'), tagline: 'tagline_sr' },
};
// The greeting is added in code, so a body that opens with one is the model
// greeting somebody - on a role contact, somebody it invented.
const OPENS_WITH_GREETING = /^\s*(hi|hello|hey|dear|good (morning|afternoon)|zdravo|dobar dan|dragi|draga|po[sš]tovan\w*)\b/i;
// The signature names the line the message sells (prompts/signature.md).
const catalogue = JSON.parse($('Offers To Text').first().json.data);
const lineOf = (code) => (catalogue.offers.find((o) => o.code === code) || {}).line || null;
// This node runs twice when a response was not valid JSON: once on the batch,
// and once more on the requests Retry Once? sent again. The second input is a
// subset, so the claim and the request are found by paired item, never by
// position.
const attempt = $prevNode.name === 'Outreach Agent Retry' ? 2 : 1;

const MAX_WORDS = 120;
// prompts/outreach.md asks a follow-up for 70; the ceiling leaves room.
const MAX_FOLLOWUP_WORDS = 90;
// A follow-up that only chases the first message is not permitted
// (prompts/outreach.md, Follow-ups).
const CHASING = [
  [/\b(did|have) you (get|see|read|had a chance)\b/i, 'did you see my last email'],
  [/\b(my|the) (last|previous|earlier) (e-?mail|message|note)\b/i, 'my last email'],
  [/\bbump(ing)? (this|it)\b/i, 'bumping this'],
  [/\b(jeste li|da li ste) (videli|pro[čc]itali|dobili)\b/i, 'jeste li videli'],
  [/\b(moj|moju) (prethodn|poslednj)\w* (poruk|mejl|e-?mail)\w*/i, 'moj prethodni mejl'],
];

// Straight from the NEVER WRITE list in prompts/outreach.md.
const BANNED = [
  [/\bhope (you('| a)?re|this (email )?finds you)\b/i, 'hope you are doing well'],
  [/\bi came across\b/i, 'I came across your company'],
  [/\bwas impressed by\b/i, 'was impressed by'],
  [/\bjust following up\b/i, 'just following up'],
  [/\bcircl(e|ing) back\b/i, 'circling back'],
  [/\btouch(ing)? base\b/i, 'touching base'],
  [/\breach(ing)? out\b/i, 'reaching out'],
  [/\blet me know if you('| wou)?d be interested\b/i, 'let me know if you would be interested'],
  [/\bdoes (that|this) resonate\b/i, 'does that resonate'],
  [/\bcompanies like yours\b/i, 'companies like yours'],
  [/\bsynerg/i, 'synergy'],
  [/\bgame[- ]chang/i, 'game-changing'],
  [/\bleverage\b/i, 'leverage'],
  // The Serbian block in prompts/outreach.md.
  [/nadam se da ste dobro/i, 'nadam se da ste dobro'],
  [/javljam (vam|Vam) se jer/i, 'javljam Vam se jer'],
  [/nai[sš]a[ol] sam na (va[sš]u|Va[sš]u)/i, 'naišao sam na Vašu firmu'],
  [/sinergij/i, 'sinergija'],
  [/revolucionar/i, 'revolucionarno'],
  [/re[sš]enje po meri/i, 'rešenje po meri'],
  [/^\s*po[sš]tovan/im, 'a greeting in the body'],
];
// A country's own invoicing system named to another country (0027): SEF went to
// Montenegro, Bosnia and Slovenia in the first regional drafts. Only names that
// mean one system are listed; "e-faktura" and "e-račun" are also plain words.
const COUNTRY_SYSTEMS = [
  [/\bSEF\b/, 'SEF', ['RS']],
  [/sistem(a|u)? elektronskih faktura/i, 'Sistem elektronskih faktura', ['RS']],
  [/fiskalizacij\w* 2\.0/i, 'Fiskalizacija 2.0', ['HR']],
  [/\bUJP\b/, 'UJP', ['SI']],
  [/\bEFI\b/, 'EFI', ['ME']],
];
const CALENDAR = /\b(calendly\.com|cal\.com|savvycal|meetings\.hubspot|book(ing)? a (call|slot)|my calendar)\b/i;
// A schema value that reached the prose. The agent picks recommended_service
// from an enum, and one draft went out reading "I run a bounded
// devops_improvement_sprint": the identifier itself, in the sentence. Nobody
// writes an underscore in an email, so any snake_case token is the model
// quoting its own schema back at the reader.
const SCHEMA_TOKEN = /\b[a-z][a-z0-9]*(?:_[a-z0-9]+)+\b/;

const EMOJI = /[←-⇿⌀-➿⬀-⯿️\u{1F000}-\u{1FAFF}]/u;

function words(text) {
  return String(text).trim().split(/\s+/).filter(Boolean).length;
}

const out = [];

for (let i = 0; i < $input.all().length; i++) {
  const req = $('Build Outreach Request').itemMatching(i).json;
  const claim = $('Claim Leads').itemMatching(i).json;
  const res = $input.all()[i].json ?? {};

  const errors = [];
  const blocks = [];
  const notes = [];
  let parsed = null;
  let raw = '';
  let usage = null;
  // Invalid JSON is the one failure worth asking again: the 27B model broke the
  // syntax in 1 of 2 drafts on 2026-09-24 (a missing quote in "subject"), with
  // strict response_format. It is asked once more, the same request, and the
  // answer is judged exactly like the first. Nothing is repaired.
  let invalidJson = false;

  if (res.error !== undefined) {
    const e = res.error;
    errors.push('Outreach model request failed: ' +
      (typeof e === 'string' ? e : (e && e.message) || JSON.stringify(e)));
  } else {
    usage = res.usage ?? null;
    const choice = Array.isArray(res.choices) ? res.choices[0] : null;
    if (!choice) errors.push('Response contained no choices');
    else if (choice.finish_reason === 'length') {
      errors.push('Response hit the token limit and is truncated');
    } else {
      raw = (choice.message && choice.message.content) || '';
      if (!raw.trim()) errors.push('Model returned no text content');
      else {
        // Ollama sometimes wraps the object in a ```json fence despite
        // response_format. The fence is transport, not content, so it is removed
        // before parsing; nothing inside it is touched. Measured: three runs on
        // 2026-09-23 failed on exactly this and nothing else.
        const unfenced = raw.trim().replace(/^```[a-zA-Z]*\s*\n?([\s\S]*?)\n?\s*```$/, '$1');
        try { parsed = JSON.parse(unfenced); } catch (e) {
          errors.push('Response is not valid JSON: ' + e.message);
          invalidJson = true;
        }
      }
    }
  }

  if (parsed !== null && (typeof parsed !== 'object' || Array.isArray(parsed))) {
    errors.push('Response is valid JSON but not a JSON object');
    parsed = null;
  }
  if (parsed !== null && typeof parsed.send !== 'boolean') {
    errors.push('send must be a boolean, got ' + typeof parsed.send);
    parsed = null;
  }

  if (attempt === 2) {
    let first = 'invalid JSON';
    try { first = $('Retry Once?').itemMatching(i).json.errors.join('; '); } catch (e) { /* the note is enough */ }
    notes.push('second attempt: the first response was rejected (' + first + ')');
  }

  if (errors.length) {
    out.push({ json: {
      agent_run_id: req.agent_run_id, lead_id: req.lead_id, company_id: req.company_id,
      company_name: req.company_name, person_name: req.person_name,
      valid: false, outcome: 'error', errors, blocks: [], notes, attempt,
      retry: attempt === 1 && invalidJson,
      error_message: 'Outreach validation failed' + (attempt === 2 ? ' after one retry' : '') + ': ' + errors.join('; '),
      draft: null, raw_response: raw, usage,
    } });
    continue;
  }

  // The agent decided there is nothing worth writing. That is a legitimate
  // outcome, not a failure - prompts/outreach.md says so in as many words.
  if (parsed.send === false) {
    out.push({ json: {
      agent_run_id: req.agent_run_id, lead_id: req.lead_id, company_id: req.company_id,
      company_name: req.company_name, person_name: req.person_name,
      valid: true, outcome: 'not_sending', errors: [], blocks: [], attempt, sequence_step: Number(req.sequence_step || 1),
      notes: [...notes, 'agent declined to write: ' + (parsed.reason_if_not_sending || 'no reason given')],
      error_message: null, draft: null, model_output: parsed, raw_response: raw, usage,
    } });
    continue;
  }

  // ---- shape of a sending draft -------------------------------------------
  for (const key of ['subject', 'body', 'hook_fact', 'hook_source', 'cta']) {
    if (typeof parsed[key] !== 'string' || !parsed[key].trim()) {
      blocks.push('missing or empty ' + key);
    }
  }
  const offers = schema.properties.offer.enum;
  if (!offers.includes(parsed.offer)) blocks.push('offer "' + parsed.offer + '" is not in the catalogue');
  const line = req.line || 'infrastructure';
  if (offers.includes(parsed.offer) && lineOf(parsed.offer) !== line) {
    blocks.push('offer ' + parsed.offer + ' belongs to the ' + lineOf(parsed.offer) + ' line; this lead is ' + line);
  }
  // prompts/outreach.md tells the agent to default to infrastructure_audit for a
  // first message even when scoring suggested something larger. Disagreeing is
  // allowed; doing it silently is not.
  if (claim.recommended_offer && parsed.offer && parsed.offer !== claim.recommended_offer) {
    notes.push('offer is ' + parsed.offer + '; scoring recommended ' + claim.recommended_offer);
  }

  const body = String(parsed.body || '');
  // A follow-up answers the first message, so its subject is that one's with
  // "Re:", set here rather than by the model: the recipient's mail client
  // groups it with the first message, and the model has nothing to add to it.
  const step = Number(req.sequence_step || 1);
  const previous = claim.previous || [];
  const firstSubject = String((previous[0] || {}).subject || '').replace(/^\s*(re|odg):\s*/i, '');
  const subject = step > 1 && firstSubject ? 'Re: ' + firstSubject : String(parsed.subject || '');
  if (step > 1 && !firstSubject) blocks.push('a follow-up with no earlier sent message to answer');

  // ---- word count ----------------------------------------------------------
  const actual = words(body);
  const ceiling = step > 1 ? MAX_FOLLOWUP_WORDS : MAX_WORDS;
  if (actual > ceiling) blocks.push('body is ' + actual + ' words, the ceiling is ' + ceiling);
  if (step > 1) {
    for (const [re, label] of CHASING) if (re.test(body)) blocks.push('a follow-up that chases the last one: "' + label + '"');
    // "Never repeat the earlier message", checked: eight words in a row taken
    // from an earlier body (six caught common phrases like "da li je"). On 2026-09-24 the 9B model's follow-up reused
    // "I run bounded improvement sprints to fix exactly that" verbatim.
    const toks = (t) => String(t).toLowerCase().normalize('NFC').match(/[\p{L}\p{N}']+/gu) || [];
    const seen = new Set();
    for (const m of previous) {
      const t = toks(m.body);
      for (let k = 0; k + 8 <= t.length; k++) seen.add(t.slice(k, k + 8).join(' '));
    }
    const mine = toks(body);
    for (let k = 0; k + 8 <= mine.length; k++) {
      const g = mine.slice(k, k + 8).join(' ');
      if (seen.has(g)) { blocks.push('repeats the earlier message: "' + g + '"'); break; }
    }
  }
  if (typeof parsed.word_count === 'number' && Math.abs(parsed.word_count - actual) > 5) {
    notes.push('model counted ' + parsed.word_count + ' words, the body has ' + actual);
  }

  // ---- banned phrases ------------------------------------------------------
  for (const [re, label] of BANNED) {
    if (re.test(body) || re.test(subject)) blocks.push('banned phrase: "' + label + '"');
  }
  const country = String(claim.country || '').trim().toUpperCase();
  for (const [re, label, countries] of COUNTRY_SYSTEMS) {
    if ((re.test(body) || re.test(subject)) && !countries.includes(country)) {
      blocks.push(label + ' named in a draft to ' + (country || 'an unknown country') + '; it is ' + countries.join('/') + ' only');
    }
  }
  if (CALENDAR.test(body)) blocks.push('a calendar link or booking ask in a first message');
  if (EMOJI.test(body) || EMOJI.test(subject)) blocks.push('contains an emoji');
  const leaked = body.match(SCHEMA_TOKEN) || subject.match(SCHEMA_TOKEN);
  if (leaked) blocks.push('a schema value reached the text: "' + leaked[0] + '"');
  const questions = (body.match(/\?/g) || []).length;
  if (questions > 1) blocks.push('body asks ' + questions + ' questions; exactly one is allowed');
  if (questions === 0) notes.push('body contains no question; the call to action may not be an ask');

  // ---- the hook must be checkable in five seconds --------------------------
  const known = claim.known_sources || [];
  const hook = String(parsed.hook_source || '').trim();
  if (hook && !known.includes(hook)) {
    // A source the research never found cannot be verified by the human who
    // approves this, which is the entire point of the field.
    blocks.push('hook_source "' + hook + '" is not one of the ' + known.length +
      ' sources the research actually found');
  }

  // ---- subject line --------------------------------------------------------
  const subjectWords = words(subject);
  if (step === 1 && (subjectWords < 4 || subjectWords > 7)) {
    notes.push('subject is ' + subjectWords + ' words; prompts/outreach.md asks for four to seven');
  }
  if (claim.person_first_name && new RegExp('\\b' + claim.person_first_name + '\\b', 'i').test(subject)) {
    blocks.push('subject contains the recipient first name');
  }

  // ---- the envelope --------------------------------------------------------
  // A role contact has no name by design: it gets the general greeting, and
  // the missing first name is not a fault. A person without one still is.
  const isRole = claim.person_kind === 'role';
  const firstName = isRole ? '' : String(claim.person_first_name || '').trim();
  if (!isRole && !firstName) blocks.push('the recipient has no first name to greet');
  // Belt and braces for the claim query's title stripping: a greeting word that
  // ends in a full stop or is a known honorific is not a name ("Hi Dr.,").
  if (!isRole && firstName && (/\.$/.test(firstName) ||
      /^(dr|mr|mrs|ms|miss|prof|ing|mag|dipl|mgr|sir|dame)$/i.test(firstName))) {
    blocks.push('the greeting would read "' + firstName + '": a title, not a first name');
  }
  if (isRole && OPENS_WITH_GREETING.test(body)) {
    blocks.push('the body opens with a greeting; this goes to a general address and the greeting is added for it');
  } else if (OPENS_WITH_GREETING.test(body)) {
    // The greeting is added below, so one in the body would be sent twice:
    // measured on a 9B follow-up, "Hi Aleksey,\n\nHi Aleksey,".
    blocks.push('the body opens with a greeting; the greeting is added by the workflow and would appear twice');
  }
  const env = ENVELOPES[req.language] || ENVELOPES.en;
  const attention = isRole && claim.attention && String(claim.attention.name || '').trim()
    ? (req.language === 'sr' ? 'N/r: ' : 'Attn: ') + String(claim.attention.name).trim() +
      (claim.attention.title ? ', ' + String(claim.attention.title).trim() : '')
    : null;
  if (attention) notes.push('marked for ' + attention.replace(/^(N\/r|Attn): /, '') + ' (' + (claim.attention.source || 'no source') + ')');
  const greeting = (attention ? attention + '\n\n' : '') +
    (isRole ? env.role_greeting : env.greeting.replace(/\{first_name\}/g, firstName));
  const signature = env.signature.replace(/\{tagline\}/g, catalogue.lines[line][env.tagline] || catalogue.lines[line].tagline)
                             .replace(/\{url\}/g, catalogue.lines[line].url);
  // A follow-up quotes the message it follows, since the send carries no
  // In-Reply-To header: the recipient sees what it refers to, and so does the
  // approval message.
  const last = previous[previous.length - 1];
  const quoted = step > 1 && last
    ? (req.language === 'sr'
        ? String(last.sent_at).slice(0, 10).split('-').reverse().join('.') + '. sam napisao:'
        : 'On ' + String(last.sent_at).slice(0, 10) + ' I wrote:') +
      '\n' + String(last.body).split('\n').map((l) => '> ' + l).join('\n')
    : null;
  const fullBody = [greeting, body, signature, quoted].filter(Boolean).join('\n\n');

  const passed = blocks.length === 0;
  out.push({ json: {
    agent_run_id: req.agent_run_id, lead_id: req.lead_id, company_id: req.company_id,
    company_name: req.company_name, person_name: req.person_name,
    valid: true,
    outcome: passed ? 'queued' : 'blocked',
    errors: [], blocks, notes, attempt,
    error_message: null,
    sequence_step: step,
    experiment: req.experiment || {},
    draft: { subject, body: fullBody, offer: parsed.offer, hook_fact: parsed.hook_fact,
             hook_source: hook, cta: parsed.cta, word_count: actual },
    block_reason: passed ? null : 'Blocked by mechanical checks: ' + blocks.join('; '),
    model_output: parsed, raw_response: raw, usage,
  } });
}

return out;

// Which half of the day this run is, and so which leads it may claim and which
// model writes them.
//
// Regional leads - a country OUTREACH_LANGUAGES gives a language with a block
// in prompts/outreach.md - are written in that language by OUTREACH_NIGHT_MODEL,
// and only between OUTREACH_NIGHT_HOUR_START and OUTREACH_NIGHT_HOUR_END. The
// 9B model's Serbian had errors in every draft; the 27B model's is usable, but
// the two do not fit in memory together and a swap cost the first 27B draft 20
// minutes on 2026-09-24. At night the batch has the GPU to itself: its runs are
// opened with window 'night', and while one is open WF-02, WF-03 and WF-04 claim
// nothing (0023_night_drafting.sql). The model loads once for the whole batch.
//
// Everyone else is written in English by the day model, outside that window.
// With OUTREACH_LANGUAGES empty nothing is regional, and the night hours simply
// claim nothing.
const doc = $('Prompt To Text').first().json.data;
// A language code and the heading of its block in prompts/outreach.md.
const LANGUAGE_BLOCKS = { sr: 'Serbian' };
const hasBlock = (lang) => LANGUAGE_BLOCKS[lang] !== undefined &&
  new RegExp('^##\\s+' + LANGUAGE_BLOCKS[lang] + '\\s*$', 'm').test(doc);

// OUTREACH_LANGUAGES maps ISO codes to a language; OpenStreetMap stores the
// code, YC the country's name, so both spellings are recognised.
const COUNTRY_NAMES = { SERBIA: 'RS', 'BOSNIA AND HERZEGOVINA': 'BA', MONTENEGRO: 'ME', CROATIA: 'HR',
                        SLOVENIA: 'SI', 'NORTH MACEDONIA': 'MK' };
const languages = {};
for (const pair of String($env.OUTREACH_LANGUAGES ?? '').split(',')) {
  const [country, lang] = pair.split(':').map((s) => (s || '').trim());
  // A language without a block would be announced to the model and then not
  // described to it; such a country stays English, as it always did.
  if (country && lang && hasBlock(lang)) languages[country.toUpperCase()] = lang;
}
for (const [name, code] of Object.entries(COUNTRY_NAMES)) {
  if (languages[code]) languages[name] = languages[code];
}

const timezone = $env.GENERIC_TIMEZONE || 'UTC';
const hour = Number(new Intl.DateTimeFormat('en-GB', { hour: '2-digit', hourCycle: 'h23', timeZone: timezone })
  .format(new Date()));
const num = (v, d) => (v === undefined || v === null || String(v).trim() === '' || isNaN(Number(v)) ? d : Number(v));
const start = num($env.OUTREACH_NIGHT_HOUR_START, 1);
const end = num($env.OUTREACH_NIGHT_HOUR_END, 5);
// The end is exclusive, as in WF-06's working hours; 23 and 5 wraps midnight.
const night = start <= end ? hour >= start && hour < end : hour >= start || hour < end;

return [{ json: {
  window: night ? 'night' : 'day',
  hour,
  timezone,
  model: night
    ? ($env.OUTREACH_NIGHT_MODEL || 'qwen3.6:27b')
    : ($env.OLLAMA_OUTREACH_MODEL || $env.OLLAMA_RESEARCH_MODEL || 'qwen9-64k:latest'),
  batch_size: night ? num($env.OUTREACH_NIGHT_BATCH_SIZE, 20) : 5,
  languages,
  regional_countries: Object.keys(languages),
} }];
